import{_ as a,o as n,c as p,a2 as s}from"./chunks/framework.F7eQ-ohH.js";const e="/bzygq/assets/a1956725fd2c413b8d6186f63a6083f7.Cgf9SN7N.png",l="/bzygq/assets/35d56c71de4b4cb2a93c99e2cf3eb471.hkCZElFi.png",i="/bzygq/assets/1e37deaa750c46f0aee7ffe819406fb6.B4QjbcJI.png",d="/bzygq/assets/3607a590efeb471e9fe3135a0fe5acd8.Ck8ip-Sb.png",r="/bzygq/assets/7aeb160ba6114342beceb89e81fac4b3.CZGY8gyU.png",v=JSON.parse('{"title":"央国企AI开发面试指南（Agent工程师）","description":"","frontmatter":{},"headers":[],"relativePath":"AI应用开发/央国企AI开发面试指南（Agent工程师）.md","filePath":"AI应用开发/央国企AI开发面试指南（Agent工程师）.md","lastUpdated":1788883925000}'),o={name:"AI应用开发/央国企AI开发面试指南（Agent工程师）.md"};function h(c,t,b,g,u,A){return n(),p("div",null,[...t[0]||(t[0]=[s('<h1 id="央国企ai开发面试指南-agent工程师" tabindex="-1">央国企AI开发面试指南（Agent工程师） <a class="header-anchor" href="#央国企ai开发面试指南-agent工程师" aria-label="Permalink to &quot;央国企AI开发面试指南（Agent工程师）&quot;">​</a></h1><p>这篇主要写给准备央国企技术岗、国企科技子公司、央企研究院、运营商科技岗、金融科技岗、能源电力信息化岗的同学。重点不是讨论“AI 会不会替代 Java”，而是把一个更现实的问题讲清楚：现在央国企技术面试仍然以 Java 后端为基础，但 AI 应用开发，尤其是 RAG 和 Agent，正在变成越来越重要的加分能力。</p><p><img src="'+e+`" alt=""></p><p>先把判断放在前面：</p><ol><li><p>央国企技术岗当前仍以传统 Java 后端、企业信息化系统、数据平台和业务系统开发为主。</p></li><li><p>AI 应用开发不会短期替代 Java 后端，但会成为技术岗候选人的重要加分项。</p></li><li><p>私企、AI 应用公司、软件厂商和市场化国企科技子公司，对 RAG、Agent、工具调用、模型接入和工程落地的考察已经更直接。</p></li><li><p>对央国企求职来说，更稳的路线不是放弃 Java 转纯 AI，而是在 Java 后端基础上叠加 RAG、Agent 和企业场景落地能力。</p></li></ol><h2 id="一、央国企技术岗正在发生什么变化" tabindex="-1">一、央国企技术岗正在发生什么变化 <a class="header-anchor" href="#一、央国企技术岗正在发生什么变化" aria-label="Permalink to &quot;一、央国企技术岗正在发生什么变化&quot;">​</a></h2><h3 id="_1-政策侧-ai-已经从概念进入场景落地" tabindex="-1">1. 政策侧：AI 已经从概念进入场景落地 <a class="header-anchor" href="#_1-政策侧-ai-已经从概念进入场景落地" aria-label="Permalink to &quot;1\\. 政策侧：AI 已经从概念进入场景落地&quot;">​</a></h3><p>2025 年国务院印发《关于深入实施“人工智能+”行动的意见》，提出推动人工智能与经济社会各行业各领域广泛深度融合，并强调模型能力、数据供给、智能算力、开源生态、人才队伍和安全能力等基础支撑。</p><p>国务院国资委也在持续推进中央企业“AI+”专项行动。公开报道中提到，中央企业下一步将更加突出应用领航、数据赋能和智算筑基，重点面向战略意义强、经济收益高、民生关联紧的高价值场景。2026 年 1 月新华网报道显示，中央企业已在能源、制造、通信等重点行业打造超一千个 AI 应用场景，国家电网、南方电网已在电力调度、故障预测等方向应用 AI，三大运营商也建设了万卡集群支撑大模型训练和应用。</p><p>这说明央国企做 AI 已经不只是概念展示，而是在往生产、调度、运维、客服、知识管理、办公自动化和行业模型建设这些具体场景里走。</p><h3 id="_2-岗位侧-传统后端仍是主体-ai-应用能力开始加权" tabindex="-1">2. 岗位侧：传统后端仍是主体，AI 应用能力开始加权 <a class="header-anchor" href="#_2-岗位侧-传统后端仍是主体-ai-应用能力开始加权" aria-label="Permalink to &quot;2\\. 岗位侧：传统后端仍是主体，AI 应用能力开始加权&quot;">​</a></h3><p>央国企的软件开发岗位不会像互联网公司那样频繁切换技术栈。大多数岗位的工作内容仍然很传统，主要围绕这些系统展开：</p><ul><li><p>企业内部业务系统</p></li><li><p>OA、门户、权限、流程审批系统</p></li><li><p>数据填报、统计分析、报表系统</p></li><li><p>生产经营管理系统</p></li><li><p>数据中台、业务中台、集成平台</p></li><li><p>行业软件和信息化平台</p></li></ul><p>这些岗位仍然需要 Java、Spring Boot、MySQL、Redis、消息队列、Linux、接口开发、日志监控和部署运维能力。</p><p>变化在于，这些传统系统正在开始叠加 AI 能力。比较常见的方向包括：</p><ul><li><p>制度文件知识库问答</p></li><li><p>智能客服和工单辅助处理</p></li><li><p>合同、招采文件、制度文件解析</p></li><li><p>设备巡检报告自动生成</p></li><li><p>生产运行日志分析</p></li><li><p>电力、能源、通信等行业场景的辅助诊断</p></li><li><p>内部办公助手和流程自动化 Agent</p></li></ul><p>所以未来一段时间，央国企技术岗更吃香的能力组合大概率会变成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传统后端开发能力</span></span>
<span class="line"><span>+ 企业业务系统理解</span></span>
<span class="line"><span>+ 数据和权限意识</span></span>
<span class="line"><span>+ RAG / Agent / 工具调用能力</span></span>
<span class="line"><span>+ 安全合规和内网部署意识</span></span></code></pre></div><h3 id="_3-面试侧-从-会不会框架-转向-能不能落地系统" tabindex="-1">3. 面试侧：从“会不会框架”转向“能不能落地系统” <a class="header-anchor" href="#_3-面试侧-从-会不会框架-转向-能不能落地系统" aria-label="Permalink to &quot;3\\. 面试侧：从“会不会框架”转向“能不能落地系统”&quot;">​</a></h3><p>传统 Java 面试主要判断候选人能不能完成企业软件开发任务。AI 应用开发面试会再往前看一步：你能不能把大模型能力做成可控、可维护、可上线的业务系统。</p><p>面试关注点会从：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>接口怎么写</span></span>
<span class="line"><span>表怎么设计</span></span>
<span class="line"><span>缓存怎么用</span></span>
<span class="line"><span>事务怎么控制</span></span></code></pre></div><p>扩展为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>知识库怎么构建</span></span>
<span class="line"><span>文档怎么分块</span></span>
<span class="line"><span>向量检索怎么优化</span></span>
<span class="line"><span>模型幻觉怎么控制</span></span>
<span class="line"><span>Agent 怎么调用工具</span></span>
<span class="line"><span>权限和审计怎么设计</span></span>
<span class="line"><span>内网环境怎么部署</span></span>
<span class="line"><span>AI 输出怎么评估</span></span></code></pre></div><p>所以 AI 应用开发不是背几个平台名词，也不是只会调一个模型接口，而是掌握一套新的工程化能力。</p><h2 id="_1、传统央国企java开发面试考察什么" tabindex="-1">1、传统央国企Java开发面试考察什么？ <a class="header-anchor" href="#_1、传统央国企java开发面试考察什么" aria-label="Permalink to &quot;1、传统央国企Java开发面试考察什么？&quot;">​</a></h2><p>传统央国企 Java 开发面试，可以先按 7 个模块准备。</p><h3 id="_1-java-语言基础" tabindex="-1">1. Java 语言基础 <a class="header-anchor" href="#_1-java-语言基础" aria-label="Permalink to &quot;1\\. Java 语言基础&quot;">​</a></h3><p>这一块主要看：</p><ul><li><p>面向对象：封装、继承、多态、接口、抽象类</p></li><li><p>集合：ArrayList、LinkedList、HashMap、ConcurrentHashMap</p></li><li><p>异常：受检异常、运行时异常、异常处理方式</p></li><li><p>泛型：类型擦除、泛型边界</p></li><li><p>反射：Class、Method、Field、动态代理</p></li><li><p>并发：线程、线程池、锁、volatile、synchronized、AQS</p></li><li><p>JVM：内存区域、类加载、GC、对象创建过程</p></li></ul><p>面试里常问：</p><table tabindex="0"><thead><tr><th>问题</th><th>考察点</th></tr></thead><tbody><tr><td>HashMap 为什么线程不安全？</td><td>数据结构、扩容、并发修改</td></tr><tr><td>ConcurrentHashMap 如何保证并发安全？</td><td>分段锁/CAS/synchronized 机制演进</td></tr><tr><td>线程池核心参数有哪些？</td><td>任务提交流程、拒绝策略、队列选择</td></tr><tr><td>synchronized 和 ReentrantLock 区别？</td><td>锁机制、可中断、公平锁、条件队列</td></tr><tr><td>JVM 内存区域包括哪些？</td><td>堆、栈、方法区、程序计数器、本地方法栈</td></tr></tbody></table><p>准备到这个程度基本够用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>能解释概念</span></span>
<span class="line"><span>能画出基本流程</span></span>
<span class="line"><span>能结合项目说明使用场景</span></span>
<span class="line"><span>能回答 1-2 层追问</span></span></code></pre></div><h3 id="_2-spring-boot-与企业应用开发" tabindex="-1">2. Spring Boot 与企业应用开发 <a class="header-anchor" href="#_2-spring-boot-与企业应用开发" aria-label="Permalink to &quot;2\\. Spring Boot 与企业应用开发&quot;">​</a></h3><p>这一块主要看：</p><ul><li><p>Spring IOC、Bean 生命周期、依赖注入</p></li><li><p>AOP、动态代理、切面应用</p></li><li><p>Spring MVC 请求处理流程</p></li><li><p>Spring Boot 自动配置原理</p></li><li><p>事务传播机制、事务失效场景</p></li><li><p>MyBatis 映射、动态 SQL、分页、批处理</p></li><li><p>参数校验、统一异常处理、统一返回结构</p></li></ul><p>面试里常问：</p><table tabindex="0"><thead><tr><th>问题</th><th>考察点</th></tr></thead><tbody><tr><td>Spring Bean 的生命周期是什么？</td><td>容器初始化、属性注入、初始化方法</td></tr><tr><td>Spring Boot 自动配置怎么生效？</td><td>starter、自动配置类、条件注解</td></tr><tr><td>@Transactional 什么时候会失效？</td><td>代理机制、异常类型、方法调用方式</td></tr><tr><td>Controller 到 Service 再到 Mapper 的调用链路是什么？</td><td>MVC 分层与工程结构</td></tr></tbody></table><p>央国企技术岗通常更关注是否具备规范开发能力，而不是是否掌握极端复杂的框架源码。准备时应把框架原理和实际业务开发结合起来。</p><h3 id="_3-数据库与数据一致性" tabindex="-1">3. 数据库与数据一致性 <a class="header-anchor" href="#_3-数据库与数据一致性" aria-label="Permalink to &quot;3\\. 数据库与数据一致性&quot;">​</a></h3><p>这一块主要看：</p><ul><li><p>MySQL 索引结构、联合索引、最左前缀</p></li><li><p>SQL 优化、执行计划、慢查询分析</p></li><li><p>事务 ACID、隔离级别、MVCC</p></li><li><p>行锁、间隙锁、死锁</p></li><li><p>表结构设计、字段类型选择</p></li><li><p>分页查询、批量写入、数据归档</p></li></ul><p>面试里常问：</p><table tabindex="0"><thead><tr><th>问题</th><th>考察点</th></tr></thead><tbody><tr><td>为什么加了索引查询仍然慢？</td><td>索引失效、回表、数据分布、执行计划</td></tr><tr><td>MySQL 事务隔离级别有哪些？</td><td>脏读、不可重复读、幻读</td></tr><tr><td>如何设计一张审批流程表？</td><td>业务建模、状态字段、审计字段</td></tr><tr><td>如何排查慢 SQL？</td><td>explain、索引、where 条件、分页方式</td></tr></tbody></table><p>央国企系统通常对数据正确性、流程留痕和审计字段比较重视。项目表达中要说明创建人、创建时间、更新时间、状态字段、操作日志、数据权限等设计。</p><h3 id="_4-redis、消息队列与常见中间件" tabindex="-1">4. Redis、消息队列与常见中间件 <a class="header-anchor" href="#_4-redis、消息队列与常见中间件" aria-label="Permalink to &quot;4\\. Redis、消息队列与常见中间件&quot;">​</a></h3><p>这一块主要看：</p><ul><li><p>Redis 数据类型和使用场景</p></li><li><p>缓存穿透、缓存击穿、缓存雪崩</p></li><li><p>缓存一致性方案</p></li><li><p>分布式锁基本实现</p></li><li><p>消息队列削峰、异步、解耦</p></li><li><p>消息重复消费、消息丢失、顺序消费</p></li><li><p>定时任务、日志系统、对象存储</p></li></ul><p>面试里常问：</p><table tabindex="0"><thead><tr><th>问题</th><th>考察点</th></tr></thead><tbody><tr><td>缓存和数据库如何保持一致？</td><td>删除缓存、延迟双删、订阅 binlog</td></tr><tr><td>如何防止重复提交？</td><td>token、幂等表、唯一索引、分布式锁</td></tr><tr><td>消息队列为什么会重复消费？</td><td>ack、重试、消费幂等</td></tr><tr><td>Redis 分布式锁有哪些问题？</td><td>过期时间、误删、续期、RedLock</td></tr></tbody></table><p>央国企面试不一定要求候选人设计高并发秒杀系统，但会关注是否理解缓存、异步、幂等、日志和异常补偿。</p><h3 id="_5-项目经历与业务表达" tabindex="-1">5. 项目经历与业务表达 <a class="header-anchor" href="#_5-项目经历与业务表达" aria-label="Permalink to &quot;5\\. 项目经历与业务表达&quot;">​</a></h3><p>项目表达建议采用以下结构：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>业务背景：系统服务什么部门、岗位或业务流程</span></span>
<span class="line"><span>核心功能：系统包含哪些主要模块</span></span>
<span class="line"><span>个人职责：本人负责哪些模块和接口</span></span>
<span class="line"><span>技术实现：用了哪些技术解决哪些具体问题</span></span>
<span class="line"><span>难点处理：遇到过什么性能、数据、权限、流程问题</span></span>
<span class="line"><span>结果产出：系统上线效果、数据规模、效率提升或管理价值</span></span></code></pre></div><p>示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>该项目面向企业内部业务管理场景，主要解决数据分散、人工登记效率低、查询统计不便的问题。</span></span>
<span class="line"><span>我负责用户权限、业务数据管理和统计查询模块，包括表结构设计、接口开发、权限校验和异常处理。</span></span>
<span class="line"><span>在查询性能方面，我针对高频查询字段建立联合索引，并对分页查询进行了优化。</span></span>
<span class="line"><span>在数据一致性方面，我通过事务控制和状态机设计保证审批流程的状态流转正确。</span></span>
<span class="line"><span>在审计方面，系统记录关键操作日志，便于后续追溯。</span></span></code></pre></div><p>避免以下表达：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我用了 Spring Boot、MyBatis、Redis、RabbitMQ、Docker，实现了用户模块、订单模块、权限模块。</span></span></code></pre></div><p>这种表达缺少业务背景、个人贡献、技术难点和结果，不利于技术面试追问。</p><h3 id="_6-工程能力" tabindex="-1">6. 工程能力 <a class="header-anchor" href="#_6-工程能力" aria-label="Permalink to &quot;6\\. 工程能力&quot;">​</a></h3><p>这一块主要看：</p><ul><li><p>Git 分支管理和冲突处理</p></li><li><p>Linux 常用命令</p></li><li><p>Docker 镜像、容器、日志查看</p></li><li><p>Nginx 反向代理</p></li><li><p>接口联调、Swagger / Apifox</p></li><li><p>日志排查、异常定位</p></li><li><p>配置文件、环境变量、部署脚本</p></li></ul><p>面试里常问：</p><table tabindex="0"><thead><tr><th>问题</th><th>考察点</th></tr></thead><tbody><tr><td>线上接口报 500 怎么排查？</td><td>日志、参数、数据库、依赖服务</td></tr><tr><td>Linux 如何查看端口占用？</td><td>netstat、ss、lsof</td></tr><tr><td>如何查看服务日志？</td><td>tail、grep、journalctl、docker logs</td></tr><tr><td>Git 冲突怎么解决？</td><td>分支、merge、rebase、冲突文件处理</td></tr></tbody></table><p>央国企技术岗通常需要候选人能参与真实开发和系统维护，工程能力不能只停留在代码层面。</p><h3 id="_7-央国企岗位匹配" tabindex="-1">7. 央国企岗位匹配 <a class="header-anchor" href="#_7-央国企岗位匹配" aria-label="Permalink to &quot;7\\. 央国企岗位匹配&quot;">​</a></h3><p>除技术问题外，央国企面试还会关注以下内容：</p><ul><li><p>是否理解目标单位业务</p></li><li><p>是否接受较稳定、流程化的开发环境</p></li><li><p>是否具备长期发展意愿</p></li><li><p>是否重视数据安全和合规</p></li><li><p>是否能与业务部门沟通</p></li><li><p>是否能接受文档、流程、审批、验收等工作</p></li></ul><p>技术类岗位不是只看“会不会写代码”，还会判断候选人是否适合企业内部系统建设环境。</p><h2 id="_2、央国企ai应用开发考察什么" tabindex="-1">2、央国企AI应用开发考察什么？ <a class="header-anchor" href="#_2、央国企ai应用开发考察什么" aria-label="Permalink to &quot;2、央国企AI应用开发考察什么？&quot;">​</a></h2><p>AI 应用开发不是算法岗。</p><p>算法岗重点是模型训练、机器学习、深度学习、论文、实验指标和算法优化。AI 应用开发重点是把大模型接入业务系统，并围绕知识库、工具调用、权限控制、流程编排、效果评估和部署运维形成完整应用。</p><h3 id="_1-ai-应用开发的标准架构" tabindex="-1">1. AI 应用开发的标准架构 <a class="header-anchor" href="#_1-ai-应用开发的标准架构" aria-label="Permalink to &quot;1\\. AI 应用开发的标准架构&quot;">​</a></h3><p>一个比较完整的 AI 应用系统，大致可以拆成下面几层：</p><p><img src="`+l+`" alt=""></p><p>如上图所示，这张图展示的是一个典型智能问答系统的分层架构。它不是单纯调用大模型 API，而是由前端交互、后端应用、知识检索、Agent 执行、模型服务以及安全运维共同组成的一套完整工程系统。</p><p>前端交互层主要负责用户入口，包括聊天窗口、文件上传、流式输出和引用来源展示。用户可以通过聊天窗口提出问题，也可以上传制度文件、业务文档或其他资料；系统在返回答案时，最好能支持流式输出，并展示答案引用了哪些原文片段，方便用户判断结果是否可信。</p><p>后端应用层是整个系统的调度中心，也是 Java 后端能力体现最明显的部分。它需要处理用户鉴权、会话管理、Prompt 组装、模型调用、工具调用调度以及日志审计。也就是说，大模型并不是直接暴露给用户，而是由后端统一封装调用逻辑、控制上下文、记录调用过程，并根据业务规则决定是否需要检索知识库或调用外部工具。</p><p>知识检索层主要对应 RAG 能力，负责把企业内部文档转化成模型可用的知识来源。它包括文档解析、文档分块、Embedding 向量化、向量数据库存储、混合检索和 Rerank 重排序。对于央国企场景来说，这一层非常关键，因为大量知识都存在于制度文件、操作规范、业务流程、设备手册和历史报告中，不能只依赖大模型自身的预训练知识。</p><p>Agent 执行层解决的是“模型如何完成多步骤任务”的问题。普通问答系统主要是回答问题，而 Agent 需要具备任务规划、Tool Calling、状态管理、错误重试和人工确认能力。比如用户提出“帮我查询某设备最近一周的异常记录并生成分析报告”，系统就需要先拆解任务，再调用数据库、日志系统或报表工具，最后汇总结果。</p><p>模型服务层提供底层模型能力，包括公有云模型 API、私有化大模型、Embedding 模型和 Rerank 模型。实际落地时，要根据数据安全要求、成本、响应速度和部署环境选择模型方案。央国企内部数据敏感度较高，很多场景不能简单把文档直接发给公网模型，因此私有化部署、内网调用和模型权限边界都需要提前考虑。</p><p>安全与运维层贯穿整个系统，包括权限控制、数据脱敏、Prompt 注入防护、调用日志、监控告警和成本统计。这一层决定系统能不能真正上线。尤其在央国企场景中，智能问答系统不仅要“能回答”，还要做到数据可控、权限隔离、结果可追溯、异常可监控、成本可统计。</p><p>所以，面试中介绍这类系统时，不要只说“我做了一个 AI 问答助手”。更好的表达是：这是一个以企业知识库为基础、以后端应用层为调度中心、结合 RAG 检索和 Agent 工具调用能力，并通过安全运维体系保障可控落地的智能问答系统。</p><h3 id="_2-大模型基础" tabindex="-1">2. 大模型基础 <a class="header-anchor" href="#_2-大模型基础" aria-label="Permalink to &quot;2\\. 大模型基础&quot;">​</a></h3><p>这一块主要看：</p><ul><li><p>Token 与 Tokenization</p></li><li><p>上下文窗口</p></li><li><p>Embedding</p></li><li><p>Temperature、Top-P、Top-K</p></li><li><p>Prompt 与 System Prompt</p></li><li><p>结构化输出</p></li><li><p>模型幻觉</p></li><li><p>Function Calling / Tool Calling</p></li><li><p>流式输出</p></li></ul><p>面试里常问：</p><table tabindex="0"><thead><tr><th>问题</th><th>考察点</th></tr></thead><tbody><tr><td>Token 是什么？为什么上下文窗口有限制？</td><td>模型输入输出机制</td></tr><tr><td>Temperature 调高会发生什么？</td><td>输出随机性和稳定性</td></tr><tr><td>为什么大模型会产生幻觉？</td><td>统计生成、知识缺失、上下文不足</td></tr><tr><td>如何让模型输出稳定 JSON？</td><td>JSON Schema、格式约束、重试校验</td></tr><tr><td>流式输出怎么实现？</td><td>SSE、WebSocket、分块返回</td></tr></tbody></table><p>准备时不用停在名词解释，至少要讲到这几件事：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>能解释大模型基本概念</span></span>
<span class="line"><span>能说明参数对输出的影响</span></span>
<span class="line"><span>能结合项目说明如何控制输出稳定性</span></span></code></pre></div><h3 id="_3-rag-知识库" tabindex="-1">3. RAG 知识库 <a class="header-anchor" href="#_3-rag-知识库" aria-label="Permalink to &quot;3\\. RAG 知识库&quot;">​</a></h3><p>RAG 是央国企 AI 应用开发中非常重要的方向。企业内部有大量制度、规范、流程、合同、报告、设备文档和业务资料，不可能全部依赖模型预训练知识，需要通过检索增强生成把外部知识接入模型，RAG 的链路可以按这个顺序理解：</p><p><img src="`+i+'" alt=""></p><p>这一块主要看：</p><ul><li><p>PDF、Word、Markdown、HTML 文档解析</p></li><li><p>chunk size 和 overlap</p></li><li><p>向量数据库：FAISS、Milvus、pgvector、Chroma 等</p></li><li><p>Embedding 模型选择</p></li><li><p>关键词检索与向量检索</p></li><li><p>混合检索</p></li><li><p>Rerank</p></li><li><p>引用来源</p></li><li><p>低置信度拒答</p></li><li><p>知识库更新和版本管理</p></li></ul><p>面试里常问：</p><table tabindex="0"><thead><tr><th>问题</th><th>考察点</th></tr></thead><tbody><tr><td>chunk size 怎么设置？</td><td>语义完整性、召回精度、上下文长度</td></tr><tr><td>为什么检索到了资料，回答仍然错误？</td><td>召回质量、重排序、Prompt、幻觉</td></tr><tr><td>如何提升 RAG 准确率？</td><td>混合检索、rerank、query rewrite、引用约束</td></tr><tr><td>如何处理表格和扫描 PDF？</td><td>OCR、结构化解析、表格抽取</td></tr><tr><td>知识库如何更新？</td><td>增量索引、版本号、过期文档处理</td></tr></tbody></table><p>央国企场景中，RAG 的重点不是只做一个聊天窗口，而是解决内部知识分散、查询效率低、回答不可追溯的问题。因此，引用来源、权限隔离、文档版本和审计日志非常重要。</p><h3 id="_4-agent-与工具调用" tabindex="-1">4. Agent 与工具调用 <a class="header-anchor" href="#_4-agent-与工具调用" aria-label="Permalink to &quot;4\\. Agent 与工具调用&quot;">​</a></h3><p>Agent 的核心不是“会聊天”，而是能够基于目标执行多步骤任务，并在过程中调用工具，典型 Agent 执行流程：</p><p><img src="'+d+`" alt=""></p><p>工具可以包括：</p><ul><li><p>数据库查询</p></li><li><p>搜索接口</p></li><li><p>文件解析</p></li><li><p>工单创建</p></li><li><p>报表生成</p></li><li><p>邮件或消息通知</p></li><li><p>业务系统 API</p></li><li><p>代码执行环境</p></li><li><p>计算器</p></li><li><p>OCR</p></li></ul><p>Agent 面试重点：</p><table tabindex="0"><thead><tr><th>考察方向</th><th>需要说明的问题</th></tr></thead><tbody><tr><td>任务规划</td><td>Agent 如何拆解复杂任务</td></tr><tr><td>工具注册</td><td>工具有哪些，参数 schema 如何定义</td></tr><tr><td>工具选择</td><td>模型如何判断调用哪个工具</td></tr><tr><td>参数校验</td><td>如何防止错误参数或越权参数</td></tr><tr><td>状态管理</td><td>多轮任务中如何保存上下文和执行状态</td></tr><tr><td>错误处理</td><td>工具失败、超时、返回异常时如何处理</td></tr><tr><td>人工确认</td><td>哪些高风险操作需要 human-in-the-loop</td></tr><tr><td>日志审计</td><td>每次工具调用如何记录和追踪</td></tr></tbody></table><p>面试里常问：</p><table tabindex="0"><thead><tr><th>问题</th><th>考察点</th></tr></thead><tbody><tr><td>Agent 和普通聊天机器人有什么区别？</td><td>目标驱动、工具调用、多步骤执行</td></tr><tr><td>Function Calling 和 Prompt 拼接工具说明有什么区别？</td><td>结构化调用、稳定性、参数约束</td></tr><tr><td>Agent 调错工具怎么办？</td><td>白名单、权限、校验、人工确认</td></tr><tr><td>Agent 死循环怎么办？</td><td>最大步数、超时、状态判断、终止条件</td></tr><tr><td>工具调用失败怎么办？</td><td>重试、降级、错误返回、人工介入</td></tr></tbody></table><p>央国企场景中，Agent 不能无约束地自动执行高风险操作。涉及生产调度、财务、人事、合同、设备控制、用户权限变更等操作时，应设计人工确认、权限校验、审批流程和审计日志。</p><h3 id="_5-mcp、langchain、langgraph、dify-等工具如何准备" tabindex="-1">5. MCP、LangChain、LangGraph、Dify 等工具如何准备 <a class="header-anchor" href="#_5-mcp、langchain、langgraph、dify-等工具如何准备" aria-label="Permalink to &quot;5\\. MCP、LangChain、LangGraph、Dify 等工具如何准备&quot;">​</a></h3><p>面试中不一定要求精通所有框架，但需要知道它们解决什么问题。</p><table tabindex="0"><thead><tr><th>工具/框架</th><th>主要作用</th><th>面试准备重点</th></tr></thead><tbody><tr><td>MCP</td><td>AI 应用连接外部工具和数据源的开放协议</td><td>工具、资源、服务端、客户端的概念</td></tr><tr><td>LangChain</td><td>大模型应用开发框架</td><td>LLM、Prompt、Retriever、Tool、Chain</td></tr><tr><td>LangGraph</td><td>图结构 Agent 编排框架</td><td>状态、节点、边、持久化、人工介入</td></tr><tr><td>Dify</td><td>低代码 AI 应用平台</td><td>Workflow、RAG、Agent、模型接入、日志</td></tr><tr><td>FastGPT</td><td>知识库问答和工作流平台</td><td>知识库、流程编排、工具调用</td></tr><tr><td>向量数据库</td><td>存储和检索 Embedding</td><td>相似度检索、索引、召回性能</td></tr></tbody></table><p>准备原则：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>至少精通一种实现方式</span></span>
<span class="line"><span>了解其他工具的定位</span></span>
<span class="line"><span>能说明为什么选择某个框架</span></span>
<span class="line"><span>能讲清框架背后的通用原理</span></span></code></pre></div><p>不要只说“我用过 Dify”或“我用过 LangChain”。更好的表达是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我使用 Dify 快速搭建过知识库问答和工作流原型，理解其 RAG、Prompt 编排、工具调用和日志观察能力。</span></span>
<span class="line"><span>在代码实现层面，我也能用 Spring Boot 接入模型 API、向量数据库和工具接口，实现可定制的 RAG / Agent 后端。</span></span></code></pre></div><h3 id="_6-安全、合规与内网部署" tabindex="-1">6. 安全、合规与内网部署 <a class="header-anchor" href="#_6-安全、合规与内网部署" aria-label="Permalink to &quot;6\\. 安全、合规与内网部署&quot;">​</a></h3><p>央国企 AI 应用面试中，安全合规是高频考点。</p><p>这一块主要看：</p><ul><li><p>内部数据是否能发送到公网模型</p></li><li><p>敏感字段脱敏</p></li><li><p>文档访问权限</p></li><li><p>不同部门知识库隔离</p></li><li><p>Prompt 注入防护</p></li><li><p>模型输出审核</p></li><li><p>工具调用权限</p></li><li><p>操作日志和审计</p></li><li><p>私有化部署</p></li><li><p>国产化适配</p></li></ul><p>面试里常问：</p><table tabindex="0"><thead><tr><th>问题</th><th>考察点</th></tr></thead><tbody><tr><td>企业内部文件能否直接上传到公有云模型？</td><td>数据安全、合规边界</td></tr><tr><td>如何防止 Prompt 注入？</td><td>指令隔离、输入检测、权限约束</td></tr><tr><td>如何避免模型泄露敏感信息？</td><td>权限检索、脱敏、输出审核</td></tr><tr><td>内网部署有哪些组件？</td><td>模型服务、向量库、应用服务、日志监控</td></tr><tr><td>Agent 调用业务接口如何控权？</td><td>RBAC、白名单、审批、人审、审计</td></tr></tbody></table><p>央国企 AI 应用的技术方案不能只考虑“能不能跑”，还要考虑“能不能上线、能不能审计、能不能解释、出错后能不能追责”。</p><h3 id="_7-ai-应用项目面试表达模板" tabindex="-1">7. AI 应用项目面试表达模板 <a class="header-anchor" href="#_7-ai-应用项目面试表达模板" aria-label="Permalink to &quot;7\\. AI 应用项目面试表达模板&quot;">​</a></h3><p>项目介绍可以按这个顺序讲：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>项目背景：该项目服务哪个业务场景，解决什么问题</span></span>
<span class="line"><span>系统架构：前端、后端、知识库、模型服务、Agent 工具层如何组成</span></span>
<span class="line"><span>核心流程：用户输入后，系统如何检索、生成、调用工具并返回结果</span></span>
<span class="line"><span>本人职责：自己负责哪些模块</span></span>
<span class="line"><span>技术难点：RAG 准确率、工具调用稳定性、权限、安全、部署等</span></span>
<span class="line"><span>优化措施：混合检索、rerank、引用来源、结构化输出、日志审计</span></span>
<span class="line"><span>项目结果：功能效果、演示能力、性能指标、业务价值</span></span></code></pre></div><p>示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>该项目是一个面向企业内部制度文件和业务流程的智能问答系统。</span></span>
<span class="line"><span>系统包含用户权限模块、文档解析模块、向量检索模块、大模型问答模块和 Agent 工具调用模块。</span></span>
<span class="line"><span>用户提问后，系统先根据用户权限筛选可检索的知识库，再通过向量检索和关键词检索召回候选片段，并使用 rerank 模型重排序。</span></span>
<span class="line"><span>模型生成答案时必须引用来源文件和原文片段；当召回置信度不足时，系统返回无法确认，避免模型编造。</span></span>
<span class="line"><span>在 Agent 部分，系统支持调用工单查询、制度检索和报表生成工具，但所有工具都经过白名单注册和参数校验，高风险操作需要人工确认。</span></span>
<span class="line"><span>我主要负责后端接口、知识库检索流程、模型调用封装和工具调用日志记录。</span></span></code></pre></div><h2 id="_3、如何使用这一系列攻略" tabindex="-1">3、如何使用这一系列攻略 <a class="header-anchor" href="#_3、如何使用这一系列攻略" aria-label="Permalink to &quot;3、如何使用这一系列攻略&quot;">​</a></h2><h3 id="_1-先确定目标岗位类型" tabindex="-1">1. 先确定目标岗位类型 <a class="header-anchor" href="#_1-先确定目标岗位类型" aria-label="Permalink to &quot;1\\. 先确定目标岗位类型&quot;">​</a></h3><p>不同岗位对 AI 应用开发的要求不同。</p><table tabindex="0"><thead><tr><th>岗位类型</th><th>Java 要求</th><th>AI 应用要求</th><th>准备重点</th></tr></thead><tbody><tr><td>普通央国企 Java 开发</td><td>高</td><td>低到中</td><td>Java、数据库、项目表达，AI 作为加分</td></tr><tr><td>央企科技子公司开发岗</td><td>高</td><td>中</td><td>Java 后端、数据平台、RAG 项目</td></tr><tr><td>运营商/金融科技岗</td><td>高</td><td>中到高</td><td>后端、数据、安全、AI 应用场景</td></tr><tr><td>AI 应用开发岗</td><td>中到高</td><td>高</td><td>RAG、Agent、模型接入、工具调用</td></tr><tr><td>算法岗</td><td>中</td><td>高，但偏算法</td><td>机器学习、深度学习、模型训练、业务场景</td></tr><tr><td>私企 AI 应用岗</td><td>中到高</td><td>高</td><td>Demo、框架、工程实现、快速交付</td></tr></tbody></table><h3 id="_2-按能力层级准备" tabindex="-1">2. 按能力层级准备 <a class="header-anchor" href="#_2-按能力层级准备" aria-label="Permalink to &quot;2\\. 按能力层级准备&quot;">​</a></h3><p><img src="`+r+`" alt=""></p><p>建议按照“五个阶段”来准备。</p><p>第一阶段先补 Java 后端基础，包括 Java、Spring Boot、MySQL、Redis、Linux 和项目表达。这个阶段的目标是先稳住央国企技术岗的基础盘，因为大多数央国企技术岗仍然以传统后端开发、企业信息化系统和业务系统建设为主。</p><p>第二阶段再进入 AI 应用基础，重点掌握大模型基础、Prompt、Embedding、RAG 和向量数据库。这个阶段不要求一上来就做复杂 Agent，而是先能讲清楚知识库问答怎么实现、企业文档怎么进入系统、模型如何基于检索结果生成答案。</p><p>第三阶段准备 Agent 工程能力，包括 Tool Calling、Function Calling、状态管理、工作流编排和 MCP。这个阶段的重点是理解 Agent 如何从“回答问题”升级为“执行任务”，也就是如何拆解目标、选择工具、生成调用参数、处理工具返回结果，并完成多步骤任务。</p><p>第四阶段要补企业落地能力，包括权限、审计、数据脱敏、私有化部署和效果评估。央国企场景下，AI 应用不能只考虑功能能不能跑，还要考虑数据能不能出内网、权限怎么隔离、日志能不能追溯、模型回答错了怎么评估和兜底。</p><p>第五阶段是面试输出，把前面的技术点转成项目介绍、技术难点、追问准备和自己的面试知识库。最终不是简单背概念，而是能把 Java 后端、RAG、Agent、安全合规和项目经验串成一套完整表达，让面试官听完知道你不仅懂技术名词，也理解系统怎么落地。</p><h3 id="_3-用一个项目覆盖核心能力" tabindex="-1">3. 用一个项目覆盖核心能力 <a class="header-anchor" href="#_3-用一个项目覆盖核心能力" aria-label="Permalink to &quot;3\\. 用一个项目覆盖核心能力&quot;">​</a></h3><p>适合央国企技术岗的 AI 应用项目方向：</p><table tabindex="0"><thead><tr><th>项目方向</th><th>适配单位</th><th>技术点</th></tr></thead><tbody><tr><td>企业制度知识库问答</td><td>各类央国企</td><td>RAG、权限、引用来源、文档解析</td></tr><tr><td>工业设备巡检 Agent</td><td>电力、能源、制造、交通</td><td>Agent、工具调用、报告生成、异常分析</td></tr><tr><td>招采文件智能解析</td><td>建筑、能源、制造、平台公司</td><td>文档解析、结构化输出、表格抽取</td></tr><tr><td>合同审核助手</td><td>金融、能源、制造、法务部门</td><td>RAG、规则校验、风险提示、人工复核</td></tr><tr><td>运维日志分析助手</td><td>运营商、金融科技、数据中心</td><td>日志分析、异常定位、工具调用</td></tr><tr><td>客服知识库助手</td><td>运营商、银行、公共服务单位</td><td>RAG、多轮问答、知识库更新</td></tr></tbody></table><p>项目至少要做到这个程度：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>能运行</span></span>
<span class="line"><span>能演示</span></span>
<span class="line"><span>有真实业务背景</span></span>
<span class="line"><span>有后端接口和数据库</span></span>
<span class="line"><span>有 RAG 或 Agent 核心流程</span></span>
<span class="line"><span>有权限或安全控制设计</span></span>
<span class="line"><span>能说明技术难点和优化方案</span></span></code></pre></div><h3 id="_4-建立面试问题库" tabindex="-1">4. 建立面试问题库 <a class="header-anchor" href="#_4-建立面试问题库" aria-label="Permalink to &quot;4\\. 建立面试问题库&quot;">​</a></h3><p>每个技术点按以下格式整理：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>问题：</span></span>
<span class="line"><span>概念：</span></span>
<span class="line"><span>项目中的使用方式：</span></span>
<span class="line"><span>可能的问题：</span></span>
<span class="line"><span>优化方案：</span></span>
<span class="line"><span>可追问点：</span></span></code></pre></div><p>示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>问题：RAG 为什么会回答错误？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>概念：</span></span>
<span class="line"><span>RAG 的回答质量取决于文档解析、分块、召回、排序、Prompt 约束和模型生成多个环节。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>项目中的使用方式：</span></span>
<span class="line"><span>系统先使用混合检索召回候选片段，再使用 rerank 模型重排序，最后把高相关片段拼入 Prompt。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>可能的问题：</span></span>
<span class="line"><span>文档解析错误、chunk 切分过细、向量召回不准、排序不合理、上下文不足、模型幻觉、知识库过期。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>优化方案：</span></span>
<span class="line"><span>调整 chunk size，增加 overlap，引入关键词检索，使用 rerank，要求答案引用来源，低置信度拒答。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>可追问点：</span></span>
<span class="line"><span>chunk size 怎么选？向量检索和关键词检索如何融合？rerank 放在哪一步？如何评估 RAG 效果？</span></span></code></pre></div><h3 id="_5-面试准备优先级" tabindex="-1">5. 面试准备优先级 <a class="header-anchor" href="#_5-面试准备优先级" aria-label="Permalink to &quot;5\\. 面试准备优先级&quot;">​</a></h3><p>如果时间有限，按以下优先级准备：</p><table tabindex="0"><thead><tr><th>优先级</th><th>内容</th><th>原因</th></tr></thead><tbody><tr><td>P0</td><td>Java 基础、Spring Boot、MySQL、项目表达</td><td>央国企技术岗基础盘</td></tr><tr><td>P1</td><td>RAG、Embedding、向量数据库、Prompt</td><td>AI 应用开发最常见方向</td></tr><tr><td>P1</td><td>Agent、Tool Calling、Function Calling</td><td>Agent 面试核心</td></tr><tr><td>P2</td><td>MCP、LangGraph、Dify、FastGPT</td><td>框架和平台加分项</td></tr><tr><td>P2</td><td>安全合规、权限、审计、私有化部署</td><td>央国企特色考点</td></tr><tr><td>P3</td><td>模型微调、训练、分布式训练</td><td>非算法岗通常不是重点</td></tr></tbody></table><h3 id="_6-最后要准备到什么程度" tabindex="-1">6. 最后要准备到什么程度 <a class="header-anchor" href="#_6-最后要准备到什么程度" aria-label="Permalink to &quot;6\\. 最后要准备到什么程度&quot;">​</a></h3><p>面试前可以用下面这几条做自检：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 能讲清传统 Java 项目的业务背景、模块设计和技术难点。</span></span>
<span class="line"><span>2. 能解释 RAG 的完整链路，并说明如何提升回答准确率。</span></span>
<span class="line"><span>3. 能解释 Agent 和普通聊天机器人的区别。</span></span>
<span class="line"><span>4. 能说明 Tool Calling 的参数校验、权限控制和异常处理。</span></span>
<span class="line"><span>5. 能结合央国企场景说明数据安全、权限隔离和审计机制。</span></span>
<span class="line"><span>6. 能完整介绍一个 AI 应用项目，而不是只罗列技术名词。</span></span>
<span class="line"><span>7. 能回答为什么央国企仍然需要 Java 后端，同时为什么 AI 应用开发会成为加分项。</span></span></code></pre></div><p>最后收一下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>央国企技术岗的底座仍然是 Java 后端和企业系统开发；</span></span>
<span class="line"><span>AI 应用开发的价值在于把大模型能力接入知识库、业务流程和行业场景；</span></span>
<span class="line"><span>Agent 方向的面试重点不是概念，而是工具调用、状态管理、安全控制和工程落地。</span></span></code></pre></div><h2 id="参考信息" tabindex="-1">参考信息 <a class="header-anchor" href="#参考信息" aria-label="Permalink to &quot;参考信息&quot;">​</a></h2><ul><li><p>新华网：《国务院印发〈关于深入实施“人工智能+”行动的意见〉》：<a href="https://www.news.cn/20250826/917de0ad1925479bb7de9785eb855708/c.html" target="_blank" rel="noreferrer">https://www.news.cn/20250826/917de0ad1925479bb7de9785eb855708/c.html</a></p></li><li><p>新华网：《为加快培育发展新质生产力、推动高质量发展提供新动能——解读〈关于深入实施“人工智能+”行动的意见〉》：<a href="https://www.news.cn/politics/20250826/5f6c013ecf1d4cf5b2da5231b34b861b/c.html" target="_blank" rel="noreferrer">https://www.news.cn/politics/20250826/5f6c013ecf1d4cf5b2da5231b34b861b/c.html</a></p></li><li><p>新华网：《国务院国资委三维度深化央企“AI+”专项行动》：<a href="https://www.news.cn/finance/20250326/e28c0cd642924c039a9f42051c5cbb1b/c.html" target="_blank" rel="noreferrer">https://www.news.cn/finance/20250326/e28c0cd642924c039a9f42051c5cbb1b/c.html</a></p></li><li><p>新华网：《中央企业“AI+”专项行动取得积极进展》：<a href="https://www.news.cn/20260128/1554b3e479cd4c5aa5a0ee6e42048bb7/c.html" target="_blank" rel="noreferrer">https://www.news.cn/20260128/1554b3e479cd4c5aa5a0ee6e42048bb7/c.html</a></p></li><li><p>OpenAI Agents SDK 文档：<a href="https://developers.openai.com/api/docs/guides/agents" target="_blank" rel="noreferrer">https://developers.openai.com/api/docs/guides/agents</a></p></li><li><p>MCP 官方文档：<a href="https://modelcontextprotocol.io/docs/getting-started/intro" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/docs/getting-started/intro</a></p></li><li><p>LangGraph 官方文档：<a href="https://docs.langchain.com/oss/javascript/langgraph/overview" target="_blank" rel="noreferrer">https://docs.langchain.com/oss/javascript/langgraph/overview</a></p></li><li><p>LangChain Tool Calling 文档：<a href="https://docs.langchain.com/oss/python/langchain/frontend/tool-calling" target="_blank" rel="noreferrer">https://docs.langchain.com/oss/python/langchain/frontend/tool-calling</a></p></li><li><p>Dify GitHub 项目说明：<a href="https://github.com/langgenius/dify" target="_blank" rel="noreferrer">https://github.com/langgenius/dify</a></p></li><li><p>BOSS 直聘公开 AI 开发岗位信息页：<a href="https://www.zhipin.com/zhaopin/be4bbbc71c55036c0nN-39g~/" target="_blank" rel="noreferrer">https://www.zhipin.com/zhaopin/be4bbbc71c55036c0nN-39g~/</a></p></li></ul>`,160)])])}const k=a(o,[["render",h]]);export{v as __pageData,k as default};
